import json

def parse_labels_json(raw):
    if raw is None:
        return None
    stripped = raw.strip()
    if not stripped:
        return None
    try:
        parsed = json.loads(stripped)
    except json.JSONDecodeError:
        return None
    if not isinstance(parsed, list):
        return None
    names: list[str] = []
    for entry in parsed:
        if isinstance(entry, Mapping):
            name = entry.get('name')
            if isinstance(name, str):
                names.append(name)
        elif isinstance(entry, str):
            names.append(entry)
    return tuple(names)
